        while (s.Count > 0) { var n = s.Pop(); if (n.Value == v) return n; if (n.Left != null) s.Push(n.Left); if (n.Right != null) s.Push(n.Right); }
        return null;
    }
    static TreeNode Chain(int n) { var root = new TreeNode(0); var c = root; for (int i = 1; i < n; i++) { c.Right = new TreeNode(i); c = c.Right; } return root; }
