static class Expect {
    static int pass, fail;
    static string Show(object o) => o is string s ? "\"" + s + "\"" : (o?.ToString() ?? "null");
    static void Report(bool ok, string what, string got, string want) {
        if (ok) { pass++; Console.WriteLine("✓ " + what); }
        else { fail++; Console.WriteLine("✗ " + what + "\n    got  " + got + "\n    want " + want); }
    }
    public static void Eq<TV>(string what, TV got, TV want) => Report(EqualityComparer<TV>.Default.Equals(got, want), what, Show(got), Show(want));
    public static void True(string what, bool ok) => Report(ok, what, ok.ToString(), "True");
